hints:
def safe_int(text, default=0):
    try:
        return int(text)
    except ValueError:
        return default
print(safe_int('abc', -1))

def parse_age(data_dict):
    try:
        age = int(data_dict['age'])
        if age < 0:
            raise ValueError()
        return f'Valid age: {age}'
    except KeyError:
        return 'Missing age'
    except ValueError:
        return 'Invalid age'
print(parse_age({'age': '24'}))
